<script setup lang="ts">import {computed,ref} from 'vue';interface Props{src?:string;alt?:string;name?:string;size?:string|number;shape?:'circle'|'rounded'|'square'};const props=withDefaults(defineProps<Props>(),{alt:'',name:'',size:40,shape:'circle'});const failed=ref(false);const initials=computed(()=>props.name.split(/\s+/).filter(Boolean).slice(0,2).map(part=>part[0]?.toUpperCase()).join('')||'?');const dimension=computed(()=>typeof props.size==='number'?`${props.size}px`:props.size)</script>
<template><span class="uv-avatar" :class="`uv-avatar--${shape}`" :style="{width:dimension,height:dimension}"><img v-if="src&&!failed" :src="src" :alt="alt||name" @error="failed=true"><span v-else aria-hidden="true">{{initials}}</span><span v-if="!alt&&name" class="uv-sr-only">{{name}}</span></span></template>
<style>.uv-avatar{display:inline-grid;place-items:center;overflow:hidden;flex:none;background:linear-gradient(135deg,var(--uv-color-primary,#2563eb),var(--uv-color-secondary,#7c3aed));color:#fff;font-family:var(--uv-font-sans,system-ui,sans-serif);font-weight:800;line-height:1}.uv-avatar img{width:100%;height:100%;object-fit:cover}.uv-avatar--circle{border-radius:50%}.uv-avatar--rounded{border-radius:var(--uv-radius-md,.625rem)}.uv-avatar--square{border-radius:0}.uv-sr-only{position:absolute!important;width:1px!important;height:1px!important;padding:0!important;margin:-1px!important;overflow:hidden!important;clip:rect(0,0,0,0)!important;white-space:nowrap!important;border:0!important}</style>
